from itertools import combinations

def find_max_sum_subset(max_val):
    best_sum = -1
    best_subset = []

    # Generate all possible subsets of the set {1, 2, ..., max_val}
    # Use combinations to generate subsets of different sizes
    for subset_size in range(1, int(max_val//2) + 1):
        for subset in combinations(range(1, max_val + 1), subset_size):
            subset_sum = sum(subset)
            subset_set = set(subset)

            # Generate all possible 2-element subsets of the current subset
            two_elem_subsets = [tuple(subset) for subset in combinations(subset_set, 2)]

            # Determine the sums of these 2-element subsets
            subset_sums = {subset_sum}

            for elem1 in subset_set:
                for elem2 in subset_set:
                    if elem1 > elem2:
                        nested_sum = elem1 + elem2
                        subset_sums.add(nested_sum)

                    # Generate subsets of the form {elem1},{elem2}
                    for other_elem in subset_set:
                        if elem1 != other_elem:
                            subset_sums.add(other_elem + elem2)
                            subset_sums.add(elem1 + other_elem)

                            # Generate subsets of the form {elem1},{elem2,elem3}
                            for elem3 in subset_set:
                                if elem1 != other_elem and elem1 != elem3 and other_elem != elem3:
                                    third_sum = other_elem + elem3
                                    subset_sums.add(third_sum)
                                    subset_sums.add(elem1 + other_elem + elem3)
                                    subset_sums.add(elem1 + other_elem)
                                    subset_sums.add(other_elem + elem3)
                                    subset_sums.add(elem1 + elem3)
                                    subset_sums.add(elem1)

            # Check if all sums are unique
            if len(subset_sums) == 2 ** (len(subset) - 2):
                if subset_sum > best_sum:
                    best_sum = subset_sum
                    best_subset = subset

    return best_subset, best_sum

# Find the maximum sum subset for numbers not exceeding 15
best_subset, max_sum = find_max_sum_subset(15)
print(f"Best subset: {best_subset}, Maximum sum: {max_sum}")
