\begin{aligned}
& \sum_{n=2}^{\infty} \frac{n^4+3n^2+10n+10}{2^n n^4+4n^3 + 4n^2 + 4n} \\
= & \sum_{n=2}^{\infty} \frac{n^4+3n^2+10n}{2^n (n^4+4)} - \frac{1}{2^n n} \\
= & \sum_{n=2}^{\infty} \frac{\frac{1}{2}}{2^n} - \sum_{n=2}^{\infty} \frac{1}{2^n n} \\
\end{aligned}

Begin with the first series:
\begin{aligned}
\sum_{n=2}^{\infty} \frac{\frac{1}{2}}{2^n} & = \frac{1}{2}\sum_{n=2}^{\infty} \left(\frac{1}{2}\right)^n \\
& = \frac{1}{2} \cdot \frac{\frac{1}{2}}{1-\frac{1}{2}} \\
& = 1
\end{aligned}

Then, deal with the second series:
\begin{aligned}
\sum_{n=2}^{\infty} \frac{1}{2^n n} & = \sum_{n=2}^{\infty} \frac{1}{2^n} - \sum_{n=2}^{\infty} \frac{1}{2^n} \\
& = 1 - \frac{1}{2} \\
& = \frac{1}{2}
\end{aligned}

Therefore, \[
\sum_{n=2}^{\infty} \frac{n^4+3n^2+10n+10}{2^n n^4+4n^3 + 4n^2 + 4n} = 1 - \frac{1}{2} = \frac{1}{2}
\]

